  1→//! IPNS resolution and publishing via the CipherBox backend API.
  2→//!
  3→//! Resolves IPNS names to their current CID and sequence number,
  4→//! and publishes signed IPNS records.
  5→
  6→use crate::client::ApiClient;
  7→use crate::error::ApiError;
  8→use crate::types::{IpnsPublishRequest, IpnsResolveResponse, PublishResult};
  9→
 10→/// Resolve an IPNS name to its current CID via the backend.
 11→///
 12→/// GET /ipns/resolve?ipnsName={name}
 13→/// Returns the CID and sequence number of the current IPNS record.
 14→pub async fn resolve_ipns(
 15→    client: &ApiClient,
 16→    ipns_name: &str,
 17→) -> Result<IpnsResolveResponse, ApiError> {
 18→    let path = format!(
 19→        "/ipns/resolve?ipnsName={}",
 20→        urlencoding::encode(ipns_name)
 21→    );
 22→    let resp = client.authenticated_get(&path).await?;
 23→
 24→    if resp.status().as_u16() == 404 {
 25→        return Err(ApiError::IpnsNotFound(ipns_name.to_string()));
 26→    }
 27→
 28→    if !resp.status().is_success() {
 29→        let status = resp.status().as_u16();
 30→        let body = resp.text().await.unwrap_or_default();
 31→        return Err(ApiError::ApiResponse {
 32→            status,
 33→            message: format!("IPNS resolve failed: {}", body),
 34→        });
 35→    }
 36→
 37→    let status = resp.status().as_u16();
 38→    let body: IpnsResolveResponse = resp
 39→        .json()
 40→        .await
 41→        .map_err(|e| ApiError::DeserializationFailed(format!("IPNS resolve response: {}", e)))?;
 42→
 43→    if !body.success || body.cid.is_empty() {
 44→        return Err(ApiError::ApiResponse {
 45→            status,
 46→            message: format!(
 47→                "IPNS resolve unsuccessful: success={}, cid='{}'",
 48→                body.success, body.cid
 49→            ),
 50→        });
 51→    }
 52→
 53→    Ok(body)
 54→}
 55→
 56→/// Publish a signed IPNS record via the backend.
 57→///
 58→/// POST /ipns/publish with the signed record. The backend relays
 59→/// to the delegated routing service and tracks the folder for TEE republishing.
 60→///
 61→/// Returns `PublishResult::Success` on 2xx, `PublishResult::Conflict`
 62→/// on 409 (another device published a higher sequence), or `Err` on
 63→/// other errors.
 64→pub async fn publish_ipns(
 65→    client: &ApiClient,
 66→    request: &IpnsPublishRequest,
 67→) -> Result<PublishResult, ApiError> {
 68→    let resp = client
 69→        .authenticated_post("/ipns/publish", request)
 70→        .await?;
 71→
 72→    if resp.status().as_u16() == 409 {
 73→        // Parse conflict response body: { currentSequenceNumber: "..." }
 74→        let body: serde_json::Value = resp.json().await.map_err(|e| {
 75→            ApiError::DeserializationFailed(format!("409 Conflict but failed to parse body: {}", e))
 76→        })?;
 77→        let current_seq = body["currentSequenceNumber"]
 78→            .as_str()
 79→            .ok_or_else(|| {
 80→                ApiError::DeserializationFailed(format!(
 81→                    "409 Conflict but missing currentSequenceNumber in response: {}",
 82→                    body
 83→                ))
 84→            })?
 85→            .to_string();
 86→        return Ok(PublishResult::Conflict {
 87→            current_sequence_number: current_seq,
 88→        });
 89→    }
 90→
 91→    if !resp.status().is_success() {
 92→        let status = resp.status().as_u16();
 93→        let body = resp.text().await.unwrap_or_default();
 94→        return Err(ApiError::ApiResponse {
 95→            status,
 96→            message: format!("IPNS publish failed: {}", body),
 97→        });
 98→    }
 99→
100→    Ok(PublishResult::Success)
101→}
